// generated by scripts/workspace.ts through payload { workspace } from Google's Discovery documents (none cached yet: the fields are the form builder's own and the names of the types they mirror); never edit this file.
// The Lexical converters of those blocks: the form renders and submits through the form builder, the qpu block computes, a Drive file embeds.
'use client'
import React from 'react'
import { FormBlock } from '@blocks/FormBlock/index'
import { QpuBlock } from '@blocks/Qpu/index'
type Node = { node: { fields: any } }
export const qpuLexicalConverters = {
  form: ({ node }: Node) => <FormBlock {...node.fields} padding={{}} />,
  qpu: ({ node }: Node) => <QpuBlock {...node.fields} />,
  driveFile: ({ node }: Node) => <iframe src={'https://drive.google.com/file/d/' + node.fields.fileId + '/preview'} title={node.fields.name ?? node.fields.fileId} data-mime-type={node.fields.mimeType} data-md5={node.fields.md5Checksum} style={{ border: 0, width: '100%', aspectRatio: '4 / 3' }} />,
}
